import {
  Group, Mesh, PlaneGeometry, BoxGeometry,
  DirectionalLight, AmbientLight, Color, DoubleSide,
  MeshPhysicalNodeMaterial, MeshBasicNodeMaterial
} from 'three/webgpu';
import { uv, mix, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const group = new Group();
  group.name = 'brand-mark-wall';

  // --- Backdrop: vertical gradient stage ---
  const stops = config.intent?.visualSpec?.colors?.gradientStops ?? [
    { at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }
  ];
  const gTop = new Color(stops[0]?.hex ?? '#1a1a22');
  const gBot = new Color(stops[stops.length - 1]?.hex ?? '#121218');
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.colorNode = mix(uniform(gTop), uniform(gBot), uv().y);
  bgMat.side = DoubleSide;
  const bg = new Mesh(new PlaneGeometry(7, 6), bgMat);
  bg.position.set(0, 0, -2.5);
  group.add(bg);

  // --- Lights: local rim + fill on top of scene's ambient/key ---
  const rim = new DirectionalLight(0xe8ecf2, 0.8);
  rim.position.set(-3.2, 1.6, -2.2);
  group.add(rim);

  const fill = new DirectionalLight(0xffffff, 0.45);
  fill.position.set(0, 0.2, 5);
  group.add(fill);

  const amb = new AmbientLight(0xffffff, 0.35);
  group.add(amb);

  // --- Kicker text + accent rule ---
  const kickerItem = items[0];
  const kicker = ctx.fontAtlas.createText(
    kickerItem?.text ?? 'AS FEATURED IN',
    { fontSize: 9, color: '#e8ecf2', align: 'center', letterSpacingPx: 1.1 }
  );
  kicker.position.set(0, 1.045, 0);
  kicker.traverse(o => {
    if (o.material) { o.material.transparent = true; o.material.opacity = 0.0; }
  });
  group.add(kicker);

  // Accent rule (<=10% area)
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = uniform(new Color('#ff2a38'));
  ruleMat.transparent = true;
  ruleMat.opacity = 0.0;
  const rule = new Mesh(new PlaneGeometry(0.5, 0.014), ruleMat);
  rule.position.set(0, 0.9, 0.001);
  group.add(rule);

  // --- Tile grid ---
  const tileW = 1.0, tileH = 0.62, tileD = 0.05;
  const xs = [-1.75, 0, 1.75];
  const ys = [0.435, -0.435];
  const tiles = [];
  const brands = items.slice(1, 7);

  function makeTileMat() {
    const m = new MeshPhysicalNodeMaterial();
    m.colorNode = mix(uniform(new Color('#1a1a22')), uniform(new Color('#121218')), uv().y);
    m.metalness = 0.5;
    m.roughness = 0.55;
    m.clearcoat = 0.2;
    m.clearcoatRoughness = 0.45;
    m.anisotropy = 0.6;
    m.anisotropyRotation = 0;
    m.transparent = true;
    m.opacity = 0;
    return m;
  }

  for (let i = 0; i < 6; i++) {
    const col = i % 3;
    const row = Math.floor(i / 3); // 0 top, 1 bottom
    const restY = ys[row];

    const mat = makeTileMat();
    const tile = new Mesh(new BoxGeometry(tileW, tileH, tileD), mat);
    tile.position.set(xs[col], restY + 0.2, 0);
    tile.userData.restY = restY;
    tile.userData.restZ = 0;
    tile.userData._wmOp = 0;

    // Brand wordmark (flat, monochrome, 78% opacity resting)
    const wm = ctx.fontAtlas.createText(
      brands[i]?.text ?? '',
      { fontSize: 11, color: '#e8ecf2', align: 'center', letterSpacingPx: 0.9 }
    );
    wm.position.set(0, 0, tileD / 2 + 0.002);
    wm.traverse(o => {
      if (o.material) { o.material.transparent = true; o.material.opacity = 0; }
    });
    tile.add(wm);
    tile.userData.wordmark = wm;

    group.add(tile);
    tiles.push(tile);

    // Per-tile hover handlers (mounted onto returned object's userData.handlers)
    tile.userData.handlers = {
      hoverEnter: () => {
        gsap.to(tile.position, { z: 0.05, duration: 0.16, ease: 'power2.out' });
        gsap.to(tile.userData, {
          _wmOp: 1.0, duration: 0.16, ease: 'power2.out',
          onUpdate: () => {
            wm.traverse(o => { if (o.material) o.material.opacity = tile.userData._wmOp; });
          }
        });
      },
      hoverLeave: () => {
        gsap.to(tile.position, { z: 0, duration: 0.16, ease: 'power2.out' });
        gsap.to(tile.userData, {
          _wmOp: 0.78, duration: 0.16, ease: 'power2.out',
          onUpdate: () => {
            wm.traverse(o => { if (o.material) o.material.opacity = tile.userData._wmOp; });
          }
        });
      }
    };
  }

  // Top-row router on group (so adapter can dispatch)
  group.userData.handlers = {
    hoverEnter: () => {},
    hoverLeave: () => {}
  };

  // --- Mount: stagger-cards (top row L->R first), fade-up ---
  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });

  // Kicker + rule settle first
  tl.to(kicker, {}, 0);
  kicker.traverse(o => { if (o.material) tl.to(o.material, { opacity: 0.6, duration: 0.5 }, 0); });
  tl.to(ruleMat, { opacity: 0.9, duration: 0.5 }, 0.05);

  tiles.forEach((t, i) => {
    const stagger = i * 0.08;
    tl.to(t.material, { opacity: 1, duration: 0.5 }, stagger);
    tl.to(t.position, { y: t.userData.restY, duration: 0.5 }, stagger);
    tl.to(t.userData, {
      _wmOp: 0.78, duration: 0.5,
      onUpdate: () => {
        t.userData.wordmark.traverse(o => {
          if (o.material) o.material.opacity = t.userData._wmOp;
        });
      }
    }, stagger);
  });

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    tiles.forEach(t => {
      gsap.killTweensOf(t.position);
      gsap.killTweensOf(t.material);
      gsap.killTweensOf(t.userData);
      t.userData.wordmark.traverse(o => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) o.material.dispose();
      });
      if (t.geometry) t.geometry.dispose();
      if (t.material) t.material.dispose();
    });
    kicker.traverse(o => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) o.material.dispose();
    });
    if (rule.geometry) rule.geometry.dispose();
    ruleMat.dispose();
    if (bg.geometry) bg.geometry.dispose();
    bgMat.dispose();
  };

  return group;
}
